-- ========== Таблица: admin_sessions ==========
CREATE TABLE IF NOT EXISTS admin_sessions (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  token VARCHAR(128) NOT NULL,
  expires_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES admin_users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ========== Таблица: content_blocks ==========
CREATE TABLE IF NOT EXISTS content_blocks (
  id INT AUTO_INCREMENT PRIMARY KEY,
  section VARCHAR(64) NOT NULL UNIQUE,
  data JSON NOT NULL,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO content_blocks (section, data, updated_at) VALUES
('services', '{"groups": [{"id": "maintenance", "lead": "Ежедневная работа, из которой складывается «дом в порядке».", "items": [{"icon": "Brush", "text": "Влажная уборка лестничных клеток по графику, мытьё окон и перил.", "title": "Уборка подъездов"}, {"icon": "Trees", "text": "Покос травы, вывоз снега, посыпка дорожек, уход за детскими площадками.", "title": "Придомовая территория"}, {"icon": "Lightbulb", "text": "Замена ламп в подъездах, ремонт светильников и датчиков движения.", "title": "Освещение мест общего пользования"}, {"icon": "DoorClosed", "text": "Доводчики, домофоны, почтовые ящики, окна и входные группы.", "title": "Подъездное оборудование"}], "label": "Содержание дома"}, {"id": "repair", "lead": "Сантехника, электрика и кровля — плановые и срочные работы.", "items": [{"icon": "Wrench", "text": "Стояки ХВС и ГВС, канализация, запорная арматура, устранение течей.", "title": "Сантехнические работы"}, {"icon": "Zap", "text": "Этажные щиты, вводные автоматы, внутридомовые сети до квартиры.", "title": "Электромонтаж"}, {"icon": "Home", "text": "Локальный ремонт кровли, межпанельные швы, козырьки над входами.", "title": "Кровля и фасад"}, {"icon": "Thermometer", "text": "Промывка и опрессовка системы, регулировка, подготовка к зиме.", "title": "Отопление"}], "label": "Ремонт и инженерия"}, {"id": "accounting", "lead": "Прозрачные квитанции и понятные расчёты по каждому дому.", "items": [{"icon": "Receipt", "text": "Формирование единого платёжного документа и расшифровка строк.", "title": "Квитанции"}, {"icon": "Gauge", "text": "Приём показаний ИПУ и ОДПУ, поверка общедомовых счётчиков.", "title": "Показания приборов учёта"}, {"icon": "FileSpreadsheet", "text": "Годовой отчёт о выполненных работах и расходовании средств.", "title": "Отчёты по дому"}, {"icon": "Scale", "text": "Сверка расчётов, рассрочка, досудебное урегулирование.", "title": "Работа с задолженностью"}], "label": "Начисления и учёт"}, {"id": "legal", "lead": "Собрания, документы и вопросы, которые решает управляющая организация.", "items": [{"icon": "Users", "text": "Подготовка, проведение и оформление протоколов ОСС.", "title": "Общие собрания"}, {"icon": "FileText", "text": "Выписка из лицевого счёта, справка о составе семьи, акты.", "title": "Справки и выписки"}, {"icon": "ShieldCheck", "text": "Комиссионные осмотры, акты о заливе и повреждении имущества.", "title": "Акты и осмотры"}, {"icon": "MessagesSquare", "text": "Регистрация обращений и ответ в установленные законом сроки.", "title": "Обращения и жалобы"}], "label": "Работа с собственниками"}], "heading": {"title": "Что мы делаем каждый день", "eyebrow": "Услуги", "description": "Полный цикл управления многоквартирным домом: от лампочки в подъезде до подготовки дома к отопительному сезону."}}', NOW()),
('about', '{"stats": [{"unit": "дома", "label": "в управлении по Белорецку", "value": "84"}, {"unit": "жильцов", "label": "обслуживаем ежедневно", "value": "12 400"}, {"unit": "", "label": "работает аварийная служба", "value": "24/7"}, {"unit": "", "label": "средний выезд по аварии", "value": "2 ч"}], "heading": {"title": "Управляем домами, а не бумагами", "eyebrow": "О компании"}, "schedule": [["Понедельник — пятница", "08:00 — 17:00"], ["Обед", "12:00 — 13:00"], ["Приём директора", "вторник, 15:00 — 17:00"]], "paragraphs": ["ООО «БелорецкДомСервис» — управляющая организация, которая обслуживает многоквартирные дома в Белорецке. Мы отвечаем за инженерные сети, подъезды, кровли и придомовую территорию: за всё, что находится за порогом квартиры и принадлежит собственникам вместе.", "Работа устроена просто: диспетчерская принимает заявку, мастер выезжает, а житель видит результат в отчёте по дому. Плановые работы согласовываем с советом дома, аварийные выполняем немедленно — в любое время суток."], "principles": [{"icon": "Clock", "text": "Каждое обращение получает номер, и вы можете узнать статус по телефону диспетчерской.", "title": "Заявка не теряется"}, {"icon": "Eye", "text": "Отчёт по каждому дому: сколько собрали, на что потратили, что запланировано.", "title": "Понятные расходы"}, {"icon": "HardHat", "text": "Сантехники, электрики и кровельщики в штате — не ждём подрядчика неделями.", "title": "Свои бригады"}], "scheduleNote": "Аварийные заявки принимаются круглосуточно, включая выходные и праздничные дни."}', NOW()),
('contacts', '{"heading": {"title": "Найти нас просто", "eyebrow": "Контакты", "description": "Приходите в офис, звоните диспетчеру или пишите на почту — обращение зарегистрируем в любом случае."}, "schedule": [["Пн — Пт", "08:00 — 17:00"], ["Обед", "12:00 — 13:00"], ["Сб — Вс", "только аварийные заявки"]]}', NOW()),
('disclosure', '{"gisLink": "https://dom.gosuslugi.ru", "heading": {"title": "Всё открыто по 731-ПП", "eyebrow": "Раскрытие информации", "description": "Управляющая организация обязана раскрывать информацию о своей работе. Мы публикуем документы в ГИС ЖКХ и дублируем их здесь — чтобы искать не пришлось."}, "sections": [{"id": "org", "docs": [{"url": "", "title": "Устав ООО «БелорецкДомСервис»"}, {"url": "", "title": "Лицензия на управление МКД"}, {"url": "", "title": "Свидетельство о постановке на налоговый учёт"}, {"url": "", "title": "Сведения о членстве в СРО и объединениях"}], "text": "Сведения об управляющей организации, реквизиты, лицензия, структура и контакты руководства.", "title": "Общая информация об организации"}, {"id": "houses", "docs": [{"url": "", "title": "Реестр многоквартирных домов на 2026 год"}, {"url": "", "title": "Технические паспорта домов"}, {"url": "", "title": "Перечень домов, где расторгнут договор управления"}], "text": "Адреса многоквартирных домов, год постройки, этажность, площадь и характеристики общего имущества.", "title": "Перечень домов в управлении"}, {"id": "contracts", "docs": [{"url": "", "title": "Типовой договор управления МКД"}, {"url": "", "title": "Перечень работ и услуг по содержанию общего имущества"}, {"url": "", "title": "Протоколы общих собраний собственников"}], "text": "Типовой договор управления, перечень работ и услуг, порядок изменения условий обслуживания.", "title": "Договоры управления"}, {"id": "reports", "docs": [{"url": "", "title": "Годовой отчёт о выполнении договора управления за 2025 год"}, {"url": "", "title": "Бухгалтерский баланс за 2025 год"}, {"url": "", "title": "Отчёт о расходовании средств текущего ремонта"}], "text": "Годовые отчёты о выполнении договора управления по каждому дому, бухгалтерская отчётность.", "title": "Отчёты и финансовая отчётность"}, {"id": "works", "docs": [{"url": "", "title": "План текущего ремонта на 2026 год"}, {"url": "", "title": "График подготовки домов к отопительному сезону"}, {"url": "", "title": "График санитарного содержания подъездов"}], "text": "План работ по текущему ремонту, подготовка к отопительному сезону, графики уборки и осмотров.", "title": "Выполняемые работы и планы"}]}', NOW()),
('company', '{"inn": "0256000000", "city": "Белорецк", "name": "ООО «БелорецкДомСервис»", "ogrn": "1120256000000", "email": "domservis.b@mail.ru", "short": "БелорецкДомСервис", "address": "453500, Республика Башкортостан, г. Белорецк, ул. Ленина, 68", "officePhone": "8 (34792) 3-15-40", "dispatchPhone": "8 (34792) 3-14-99", "officePhoneHref": "tel:+73479231540", "dispatchPhoneHref": "tel:+73479231499"}', NOW());

-- ========== Таблица: news ==========
CREATE TABLE IF NOT EXISTS news (
  id INT AUTO_INCREMENT PRIMARY KEY,
  category VARCHAR(32) NOT NULL,
  news_date DATE NOT NULL,
  title VARCHAR(255) NOT NULL,
  excerpt TEXT NOT NULL,
  body JSON NOT NULL,
  addresses VARCHAR(500) NULL,
  images JSON NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO news (id, category, news_date, title, excerpt, body, addresses, images, created_at, updated_at) VALUES
(1, 'Отключения', '2026-08-24', 'Плановое отключение горячей воды на Ленина, 62–70', 'С 26 по 28 августа проводим замену участка розлива ГВС. Холодная вода и отопление работают в обычном режиме.', '["С 26 по 28 августа с 09:00 до 18:00 будет отключено горячее водоснабжение в домах по ул. Ленина, 62, 64, 68, 70.", "Причина — замена изношенного участка розлива горячей воды в подвальных помещениях. Работы выполняются собственной бригадой, подача возобновляется вечером каждого дня после опрессовки.", "Если после включения из крана идёт мутная или ржавая вода — дайте стечь 3–5 минут. Если ситуация не изменилась, оставьте заявку в диспетчерской."]', 'Ленина, 62 · 64 · 68 · 70', '["https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/22b8bcc2-7679-4834-997a-c1e54720c7fe.jpg"]', '2026-09-13 07:13:48', '2026-09-13 07:13:48'),
(2, 'Работы', '2026-08-18', 'Завершён ремонт кровли на Косоротова, 11', 'Заменено 340 м² мягкой кровли, обновлены примыкания и воронки внутреннего водостока.', '["Бригада кровельщиков завершила капитальный ремонт мягкой кровли дома по ул. Косоротова, 11. Заменено 340 м² покрытия, восстановлены примыкания к вентшахтам и парапетам, прочищены воронки внутреннего водостока.", "Работы приняты советом дома, акт подписан. Гарантия на выполненные работы — 5 лет.", "Собственникам верхних этажей, у которых ранее фиксировались протечки, просим сообщить о состоянии потолков после первых дождей."]', 'Косоротова, 11', '["https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/658ab32f-a043-4588-a350-234f07734679.jpg", "https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/ca89026e-7b8e-464c-bae3-cf2fdabadf1a.jpg"]', '2026-09-13 07:13:48', '2026-09-13 07:13:48'),
(3, 'Объявления', '2026-08-12', 'Подготовка к отопительному сезону: доступ в подвалы и квартиры', 'До 10 сентября проводим опрессовку и промывку систем отопления. Просим обеспечить доступ к стоякам.', '["До 10 сентября во всех домах в управлении проводятся гидравлические испытания и промывка систем отопления — это обязательный этап подготовки к зиме.", "Просим собственников обеспечить доступ к стоякам отопления в квартирах. Если стояк зашит коробом или мебелью, заранее сообщите в диспетчерскую — мастер согласует удобное время.", "График по каждому дому вывешен на информационных стендах в подъездах."]', NULL, '[]', '2026-09-13 07:13:48', '2026-09-13 07:13:48'),
(4, 'Отчёты', '2026-07-30', 'Отчёты по домам за первое полугодие 2026 года', 'Опубликованы отчёты о доходах и расходах: сколько собрано, на что израсходовано, что запланировано.', '["В разделе «Раскрытие информации» опубликованы отчёты об исполнении договора управления за первое полугодие 2026 года по каждому дому.", "В отчёте указано: начислено и собрано за содержание жилья, перечень выполненных работ с суммами, остаток средств на конец периода и план работ на второе полугодие.", "Замечания и предложения по отчёту принимаются от совета дома в письменном виде в течение 30 дней."]', NULL, '[]', '2026-09-13 07:13:48', '2026-09-13 07:13:48'),
(5, 'Работы', '2026-07-21', 'Обновлено освещение в подъездах пяти домов', 'Установлены светодиодные светильники с датчиками движения — расход электроэнергии на ОДН снизится.', '["В подъездах домов по ул. Точисского, 19, 21 и ул. 5 Июля, 8, 10, 12 заменены светильники на светодиодные с датчиками движения и освещённости.", "Ожидаемое снижение расхода электроэнергии на общедомовые нужды — до 60%, что отразится в квитанциях уже в следующем расчётном периоде.", "О неработающем светильнике сообщайте в диспетчерскую с указанием подъезда и этажа."]', 'Точисского, 19 · 21 · 5 Июля, 8 · 10 · 12', '["https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/ee4802a0-8169-41ca-ac7b-030188303c79.jpg"]', '2026-09-13 07:13:48', '2026-09-13 07:13:48'),
(6, 'Объявления', '2026-07-08', 'Показания счётчиков — до 25 числа каждого месяца', 'Передать показания можно через форму на сайте, по телефону диспетчерской или в ГИС ЖКХ.', '["Напоминаем: показания индивидуальных приборов учёта передаются с 20 по 25 число каждого месяца.", "Если показания не переданы вовремя, начисление производится по среднемесячному расходу, а после трёх месяцев — по нормативу с повышающим коэффициентом.", "Удобнее всего передать показания через форму на сайте — они попадают напрямую в расчётный отдел."]', NULL, '[]', '2026-09-13 07:13:48', '2026-09-13 07:13:48');

ALTER TABLE news AUTO_INCREMENT = 7;

-- ========== Таблица: media_library ==========
CREATE TABLE IF NOT EXISTS media_library (
  id INT AUTO_INCREMENT PRIMARY KEY,
  url TEXT NOT NULL,
  filename VARCHAR(255) NULL,
  label VARCHAR(255) NULL,
  content_type VARCHAR(120) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;

